draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';

  // Bird
  ctx.beginPath();
  ctx.arc(W/2, H/2, 20, 0, 2*Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.arc(W/2, H/2 - 30 + 20*Math.sin(t), 10, 0, 2*Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2);
  ctx.lineTo(W/2 + 30 + 10*Math.cos(t), H/2 - 20 + 10*Math.sin(t));
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2);
  ctx.lineTo(W/2 - 30 - 10*Math.cos(t), H/2 - 20 + 10*Math.sin(t));
  ctx.stroke();

  // Fish
  ctx.beginPath();
  ctx.arc(W/2 + 100, H/2 + 50, 20, 0, 2*Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + 100, H/2 + 50);
  ctx.lineTo(W/2 + 130 + 10*Math.sin(t), H/2 + 70);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + 100, H/2 + 50);
  ctx.lineTo(W/2 + 70 - 10*Math.sin(t), H/2 + 70);
  ctx.stroke();

  // Butterfly
  ctx.beginPath();
  ctx.arc(W/2 - 100, H/2 - 50, 15, 0, 2*Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 - 100, H/2 - 50);
  ctx.lineTo(W/2 - 80 + 10*Math.cos(t), H/2 - 30 + 10*Math.sin(t));
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 - 100, H/2 - 50);
  ctx.lineTo(W/2 - 120 - 10*Math.cos(t), H/2 - 30 + 10*Math.sin(t));
  ctx.stroke();

  ctx.restore();
}
